#!/usr/bin/perl
use strict;
use warnings;
use File::Find;

my $REPO = '/bench/repo';
my $MODULE = 'github.com/usememos/memos';

# symbol_id => { file => ..., pkg => ..., name => ..., callers => {} }
my %symbols;
# pkg_import_path => { name => symbol_id }
my %pkg_funcs;
# file => { pkg_name, import_path, imports => {}, dot_imports => [] }
my %files;

sub strip_go_comments {
    my ($s) = @_;
  # block comments
    $s =~ s/\/\*.*?\*\///gs;
  # line comments
    $s =~ s/\/\/.*$//mg;
    return $s;
}

sub pkg_import_path {
    my ($filepath) = @_;
    my $rel = $filepath;
    $rel =~ s/^\Q$REPO\E\/?//;
    $rel =~ s/\/[^\/]+$//;  # remove filename
    return $MODULE . ($rel ? "/$rel" : '');
}

sub parse_imports {
    my ($content) = @_;
    my %imports;
    my @dot;
    while ($content =~ /\bimport\s+(?:\(\s*([\s\S]*?)\)|"([^"]+)"|(\w+)\s+"([^"]+)")/g) {
        if ($1) {
            my $block = $1;
            while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
                my ($alias, $path) = ($1, $2);
                if (!defined $alias) {
                    $alias = $path;
                    $alias =~ s/.*\///;
                }
                if ($alias eq '.') {
                    push @dot, $path;
                } else {
                    $imports{$alias} = $path;
                }
            }
        } elsif ($2) {
            my $path = $2;
            my $alias = $path;
            $alias =~ s/.*\///;
            $imports{$alias} = $path;
        } elsif ($3 && $4) {
            my ($alias, $path) = ($3, $4);
            if ($alias eq '.') {
                push @dot, $path;
            } else {
                $imports{$alias} = $path;
            }
        }
    }
    return (\%imports, \@dot);
}

sub register_symbol {
    my ($sym_id, $file, $pkg_path, $display_name, $recv) = @_;
    if (!exists $symbols{$sym_id}) {
        $symbols{$sym_id} = {
            file => $file,
            pkg => $pkg_path,
            name => $display_name,
            recv => $recv,
            callers => {},
        };
        $pkg_funcs{$pkg_path}{$display_name} = $sym_id;
        # also register without pointer on receiver for method lookup
        if ($recv && $recv =~ /^\*(.+)$/) {
            my $bare = $1 . '.' . ($display_name =~ /\./ ? '' : '');
            if ($display_name =~ /^(.+)\.(.+)$/) {
                $pkg_funcs{$pkg_path}{$1 . '.' . $2} = $sym_id unless exists $pkg_funcs{$pkg_path}{$1 . '.' . $2};
            }
        }
    }
}

sub extract_declarations {
    my ($file, $content, $pkg_path) = @_;
    while ($content =~ /\bfunc\s+(?:\((\w+)\s+(\*?\w+)\)\s+)?(\w+)\s*\(/g) {
        my ($recv_var, $recv_type, $name) = ($1, $2, $3);
        my $display;
        my $recv = '';
        if (defined $recv_type) {
            $display = "$recv_type.$name";
            $recv = $recv_type;
        } else {
            $display = $name;
        }
        my $sym_id = "$pkg_path::$display";
        register_symbol($sym_id, $file, $pkg_path, $display, $recv);
    }
}

sub resolve_pkg_from_alias {
    my ($alias, $imports, $dot_imports, $local_pkg_path) = @_;
    if ($alias eq '') {
        return $local_pkg_path;
    }
    if (exists $imports->{$alias}) {
        return $imports->{$alias};
    }
    # could be same-package reference mistaken - no
    return undef;
}

sub add_call {
    my ($target_sym_id, $caller_id) = @_;
    return unless defined $target_sym_id && defined $caller_id;
    return if $target_sym_id eq $caller_id;
    $symbols{$target_sym_id}{callers}{$caller_id} = 1 if exists $symbols{$target_sym_id};
}

sub resolve_call_target {
    my ($pkg_alias, $func_name, $imports, $dot_imports, $local_pkg_path) = @_;
    my @targets;

    if (defined $pkg_alias) {
        my $pkg_path = resolve_pkg_from_alias($pkg_alias, $imports, $dot_imports, $local_pkg_path);
        if ($pkg_path && exists $pkg_funcs{$pkg_path}) {
            if (exists $pkg_funcs{$pkg_path}{$func_name}) {
                push @targets, $pkg_funcs{$pkg_path}{$func_name};
            }
            # method call on package? rare
        }
        # dot imports
        for my $dp (@$dot_imports) {
            if (exists $pkg_funcs{$dp} && exists $pkg_funcs{$dp}{$func_name}) {
                push @targets, $pkg_funcs{$dp}{$func_name};
            }
        }
    } else {
        # unqualified - same package
        if (exists $pkg_funcs{$local_pkg_path} && exists $pkg_funcs{$local_pkg_path}{$func_name}) {
            push @targets, $pkg_funcs{$local_pkg_path}{$func_name};
        }
        # dot imports
        for my $dp (@$dot_imports) {
            if (exists $pkg_funcs{$dp} && exists $pkg_funcs{$dp}{$func_name}) {
                push @targets, $pkg_funcs{$dp}{$func_name};
            }
        }
    }
    return @targets;
}

sub extract_calls_in_file {
    my ($file, $content, $meta) = @_;
    my $local_pkg_path = $meta->{import_path};
    my $imports = $meta->{imports};
    my $dot_imports = $meta->{dot_imports};

    my @func_stack;
    my $brace_depth = 0;
    my $in_func = 0;
    my $current_caller = undef;

    # Split by func declarations to assign bodies to callers
    my @parts = split(/\b(func\s+)/, $content);
    # reassemble scanning each function
    for (my $i = 1; $i < @parts; $i += 2) {
        my $prefix = $parts[$i];      # "func "
        my $rest = $parts[$i+1] // '';
        if ($rest !~ /^((?:\(\w+\s+\*?\w+\)\s+)?\w+)\s*\([^)]*\)\s*(?:\([^)]*\)\s*)?{/s) {
            next;
        }
        my $sig = $1;
        my $body_start = pos($rest);
        my $body = substr($rest, $body_start);

        my $caller_display;
        if ($sig =~ /^\((\w+)\s+(\*?\w+)\)\s+(\w+)$/) {
            $caller_display = "$2.$3";
        } elsif ($sig =~ /^(\w+)$/) {
            $caller_display = $1;
        } else {
            next;
        }
        my $caller_id = "$local_pkg_path::$caller_display";

        # find matching close brace for function body (first top-level)
        my $depth = 1;
        my $pos = 0;
        my $len = length($body);
        while ($pos < $len && $depth > 0) {
            my $c = substr($body, $pos, 1);
            if ($c eq '{') { $depth++; }
            elsif ($c eq '}') { $depth--; }
            $pos++;
        }
