            next;
        }
        my $sig = $1;
        my $body_start = pos($rest);
        my $body = substr($rest, $body_start);

        my $caller_display;
        if ($sig =~ /^\((\w+)\s+(\*?\w+)\)\s+(\w+)$/) {
            $caller_display = "$2.$3";
        } elsif ($sig =~ /^(\w+)$/) {
            $caller_display = $1;
        } else {
            next;
        }
        my $caller_id = "$local_pkg_path::$caller_display";

        # find matching close brace for function body (first top-level)
        my $depth = 1;
        my $pos = 0;
        my $len = length($body);
        while ($pos < $len && $depth > 0) {
            my $c = substr($body, $pos, 1);
            if ($c eq '{') { $depth++; }
            elsif ($c eq '}') { $depth--; }
            $pos++;
        }
        my $func_body = substr($body, 0, $pos);

        # nested func literals as separate callers
        extract_calls_from_body($func_body, $caller_id, $local_pkg_path, $imports, $dot_imports, 1);
    }

    # package init code outside functions - use file-level pseudo caller
    my $init_caller = "$local_pkg_path::<init::$file>";
    extract_calls_from_body($content, $init_caller, $local_pkg_path, $imports, $dot_imports, 0);
}

sub extract_calls_from_body {
    my ($body, $default_caller, $local_pkg_path, $imports, $dot_imports, $skip_outer_func_sigs) = @_;

    # Handle nested func literals
    my $work = $body;
    if ($skip_outer_func_sigs) {
        # remove first opening segment up to first { for outer - already body only
    }

    # Process nested func ... { ... } literals
    while ($work =~ /\bfunc\s*(?:\((\w+)\s+(\*?\w+)\)\s+)?(\w+)?\s*\([^)]*\)\s*(?:\([^)]*\)\s*)?{/g) {
        my $start = pos($work) - 1;
        my $recv_type = $2;
        my $name = $3;
        my $depth = 1;
        my $pos = $start + 1;
        while ($pos < length($work) && $depth > 0) {
            my $c = substr($work, $pos, 1);
            if ($c eq '{') { $depth++; }
            elsif ($c eq '}') { $depth--; }
            $pos++;
        }
        my $literal_body = substr($work, $start, $pos - $start);
        my $lit_caller;
        if (defined $recv_type && defined $name) {
            $lit_caller = "$local_pkg_path::$recv_type.$name";
        } elsif (defined $name) {
            $lit_caller = "$local_pkg_path::$name";
        } else {
            $lit_caller = "$default_caller<literal>";
        }
        my $inner = substr($literal_body, index($literal_body, '{') + 1);
        $inner = substr($inner, 0, -1);
        scan_calls($inner, $lit_caller, $local_pkg_path, $imports, $dot_imports);
    }

    scan_calls($work, $default_caller, $local_pkg_path, $imports, $dot_imports);
}

sub scan_calls {
    my ($text, $caller_id, $local_pkg_path, $imports, $dot_imports) = @_;

    # Remove string literals to avoid false positives
    my $t = $text;
    $t =~ s/`[^`]*`//g;
    $t =~ s/"([^"\\]|\\.)*"//g;

    # Qualified calls: pkg.Func( or pkg.Type.Method(
    while ($t =~ /(?:^|[^\w\.])([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
        my ($pkg_alias, $name) = ($1, $2);
        # skip type assertions and composite literals heuristics
        next if $pkg_alias eq 'return' || $pkg_alias eq 'case';
        for my $tid (resolve_call_target($pkg_alias, $name, $imports, $dot_imports, $local_pkg_path)) {
            add_call($tid, $caller_id);
        }
    }

    # Unqualified calls - careful with keywords
    my %keywords = map { $_ => 1 } qw(
        if for switch return func go defer else range case break continue default fallthrough
        map chan struct interface select
    );
    while ($t =~ /(?:^|[^\w\.])([A-Za-z_]\w*)\s*\(/g) {
        my $name = $1;
        next if $keywords{$name};
        next if $name eq 'make' || $name eq 'new' || $name eq 'panic' || $name eq 'recover' || $name eq 'print' || $name eq 'println' || $name eq 'close' || $name eq 'append' || $name eq 'len' || $name eq 'cap' || $name eq 'copy' || $name eq 'delete' || $name eq 'complex' || $name eq 'real' || $name eq 'imag';
        for my $tid (resolve_call_target(undef, $name, $imports, $dot_imports, $local_pkg_path)) {
            add_call($tid, $caller_id);
        }
    }
}

