#!/usr/bin/perl
use strict;
use warnings;

my $REPO = '/bench/repo';
my $MODULE = 'github.com/usememos/memos';

my %symbols;
my %pkg_funcs;
my %files;

sub sym_key {
    my ($pkg_path, $display) = @_;
    return "${pkg_path}::${display}";
}

sub strip_go_comments {
    my ($s) = @_;
    $s =~ s/\/\*.*?\*\///gs;
    $s =~ s/\/\/.*$//mg;
    return $s;
}

sub pkg_import_path {
    my ($filepath) = @_;
    my $rel = $filepath;
    $rel =~ s/^\Q$REPO\E\/?//;
    $rel =~ s/\/[^\/]+$//;
    return $MODULE . ($rel ? "/$rel" : '');
}

sub parse_imports {
    my ($content) = @_;
    my %imports;
    my @dot;
    while ($content =~ /\bimport\s+(?:\(\s*([\s\S]*?)\)|"([^"]+)"|(\w+)\s+"([^"]+)")/g) {
        if ($1) {
            my $block = $1;
            while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
                my ($alias, $path) = ($1, $2);
                if (!defined $alias) {
                    $alias = $path;
                    $alias =~ s/.*\///;
                }
                if ($alias eq '.') {
                    push @dot, $path;
                } else {
                    $imports{$alias} = $path;
                }
            }
        } elsif ($2) {
            my $path = $2;
            my $alias = $path;
            $alias =~ s/.*\///;
            $imports{$alias} = $path;
        } elsif ($3 && $4) {
            my ($alias, $path) = ($3, $4);
            if ($alias eq '.') {
                push @dot, $path;
            } else {
                $imports{$alias} = $path;
            }
        }
    }
    return (\%imports, \@dot);
}

sub register_symbol {
    my ($sym_id, $file, $pkg_path, $display_name, $recv) = @_;
    if (!exists $symbols{$sym_id}) {
        $symbols{$sym_id} = {
            file => $file,
            pkg => $pkg_path,
            name => $display_name,
            recv => $recv,
            callers => {},
        };
        $pkg_funcs{$pkg_path}{$display_name} = $sym_id;
        if ($recv && $recv =~ /^\*(.+)$/) {
            my $bare_type = $1;
            if ($display_name =~ /^(.+)\.(.+)$/) {
                my ($rtype, $mname) = ($1, $2);
                if ($rtype eq $recv) {
                    $pkg_funcs{$pkg_path}{"${bare_type}.${mname}"} = $sym_id
                        unless exists $pkg_funcs{$pkg_path}{"${bare_type}.${mname}"};
                }
            }
        }
    }
}

sub extract_declarations {
    my ($file, $content, $pkg_path) = @_;
    while ($content =~ /\bfunc\s+(?:\((\w+)\s+(\*?\w+)\)\s+)?(\w+)\s*\(/g) {
        my ($recv_var, $recv_type, $name) = ($1, $2, $3);
        my ($display, $recv);
        if (defined $recv_type) {
            $display = "${recv_type}.${name}";
            $recv = $recv_type;
        } else {
            $display = $name;
            $recv = '';
        }
        register_symbol(sym_key($pkg_path, $display), $file, $pkg_path, $display, $recv);
    }
}

sub resolve_pkg_from_alias {
    my ($alias, $imports) = @_;
    return $imports->{$alias} if exists $imports->{$alias};
    return undef;
}

sub add_call {
    my ($target_sym_id, $caller_id) = @_;
    return unless defined $target_sym_id && defined $caller_id;
    return if $target_sym_id eq $caller_id;
    return unless exists $symbols{$target_sym_id};
    $symbols{$target_sym_id}{callers}{$caller_id} = 1;
}

sub resolve_call_target {
    my ($pkg_alias, $func_name, $imports, $dot_imports, $local_pkg_path) = @_;
    my @targets;
    if (defined $pkg_alias) {
        my $pkg_path = resolve_pkg_from_alias($pkg_alias, $imports);
        if ($pkg_path && exists $pkg_funcs{$pkg_path}{$func_name}) {
            push @targets, $pkg_funcs{$pkg_path}{$func_name};
        }
        for my $dp (@$dot_imports) {
            if (exists $pkg_funcs{$dp}{$func_name}) {
                push @targets, $pkg_funcs{$dp}{$func_name};
            }
        }
    } else {
        if (exists $pkg_funcs{$local_pkg_path}{$func_name}) {
            push @targets, $pkg_funcs{$local_pkg_path}{$func_name};
        }
        for my $dp (@$dot_imports) {
            if (exists $pkg_funcs{$dp}{$func_name}) {
                push @targets, $pkg_funcs{$dp}{$func_name};
            }
        }
    }
    return @targets;
}

sub extract_brace_block {
    my ($text, $start) = @_;
    my $depth = 0;
    my $pos = $start;
    my $len = length($text);
    while ($pos < $len) {
        my $c = substr($text, $pos, 1);
        if ($c eq '{') { $depth++; }
        elsif ($c eq '}') {
            $depth--;
            if ($depth == 0) {
                return substr($text, $start, $pos - $start + 1);
            }
        }
        $pos++;
    }
    return substr($text, $start);
}

sub extract_calls_in_file {
    my ($file, $content, $meta) = @_;
    my $local_pkg_path = $meta->{import_path};
    my $imports = $meta->{imports};
    my $dot_imports = $meta->{dot_imports};

    my @parts = split(/\b(func\s+)/, $content);
    for (my $i = 1; $i < @parts; $i += 2) {
        my $rest = $parts[$i + 1] // '';
        if ($rest !~ /^((?:\(\w+\s+\*?\w+\)\s+)?\w+)\s*\([^)]*\)\s*(?:\([^)]*\)\s*)?\{/s) {
            next;
        }
        my $sig = $1;
        my $body_start = pos($rest) - 1;
        my $func_block = extract_brace_block($rest, $body_start);
        my $func_body = substr($func_block, 1, length($func_block) - 2);

        my $caller_display;
        if ($sig =~ /^\((\w+)\s+(\*?\w+)\)\s+(\w+)$/) {
            $caller_display = "$2.$3";
        } elsif ($sig =~ /^(\w+)$/) {
            $caller_display = $1;
        } else {
            next;
        }
        my $caller_id = sym_key($local_pkg_path, $caller_display);
        process_body($func_body, $caller_id, $local_pkg_path, $imports, $dot_imports);
    }
}

sub process_body {
    my ($body, $default_caller, $local_pkg_path, $imports, $dot_imports) = @_;
    my $work = $body;

    # Nested func literals: extract and scan separately, then remove from work
    while ($work =~ /\bfunc\s*(?:\((\w+)\s+(\*?\w+)\)\s+)?(\w+)?\s*\([^)]*\)\s*(?:\([^)]*\)\s*)?\{/g) {
        my $start = pos($work) - 1;
        my $recv_type = $2;
        my $name = $3;
        my $literal_block = extract_brace_block($work, $start);
        my $inner = substr($literal_block, 1, length($literal_block) - 2);

        my $lit_caller;
        if (defined $recv_type && defined $name) {
            $lit_caller = sym_key($local_pkg_path, "${recv_type}.${name}");
        } elsif (defined $name) {
            $lit_caller = sym_key($local_pkg_path, $name);
        } else {
            $lit_caller = "${default_caller}<literal>";
        }
        process_body($inner, $lit_caller, $local_pkg_path, $imports, $dot_imports);

        my $matched = substr($work, $start, length($literal_block));
        substr($work, $start, length($literal_block), ' ' x length($literal_block));
        pos($work) = $start;
    }

    scan_calls($work, $default_caller, $local_pkg_path, $imports, $dot_imports);
}

sub scan_calls {
    my ($text, $caller_id, $local_pkg_path, $imports, $dot_imports) = @_;
    my $t = $text;
    $t =~ s/`[^`]*`//g;
    $t =~ s/"([^"\\]|\\.)*"//g;

    while ($t =~ /(?:^|[^\w\.])([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
        my ($pkg_alias, $name) = ($1, $2);
        next if $pkg_alias eq 'return' || $pkg_alias eq 'case';
        for my $tid (resolve_call_target($pkg_alias, $name, $imports, $dot_imports, $local_pkg_path)) {
            add_call($tid, $caller_id);
        }
    }

    my %keywords = map { $_ => 1 } qw(
        if for switch return func go defer else range case break continue default fallthrough
        map chan struct interface select
    );
    while ($t =~ /(?:^|[^\w\.])([A-Za-z_]\w*)\s*\(/g) {
        my $name = $1;
        next if $keywords{$name};
        next if $name =~ /^(make|new|panic|recover|print|println|close|append|len|cap|copy|delete|complex|real|imag)$/;
        for my $tid (resolve_call_target(undef, $name, $imports, $dot_imports, $local_pkg_path)) {
            add_call($tid, $caller_id);
        }
    }
}

sub process_go_file {
    my ($path) = @_;
    return if $path =~ /\/vendor\//;
    open my $fh, '<', $path or return;
    local $/;
    my $raw = <$fh>;
    close $fh;

    my $content = strip_go_comments($raw);
    my ($imports, $dot_imports) = parse_imports($content);
    my $import_path = pkg_import_path($path);

    $files{$path} = {
        import_path => $import_path,
        imports => $imports,
        dot_imports => $dot_imports,
        content => $content,
    };
    extract_declarations($path, $content, $import_path);
}

open my $fl, '-|', 'find', $REPO, '-name', '*.go', '!', '-path', '*/vendor/*' or die $!;
while (my $path = <$fl>) {
    chomp $path;
    process_go_file($path);
}
close $fl;

for my $path (keys %files) {
    my $meta = $files{$path};
    extract_calls_in_file($path, $meta->{content}, $meta);
}

my @internal;
for my $sym_id (keys %symbols) {
    my $s = $symbols{$sym_id};
    next unless $s->{file} =~ /\/internal\//;
    my $fanin = scalar keys %{$s->{callers}};
    push @internal, {
        sym_id => $sym_id,
        file => $s->{file},
        pkg => $s->{pkg},
        name => $s->{name},
        fanin => $fanin,
        callers => $s->{callers},
    };
}

@internal = sort { $b->{fanin} <=> $a->{fanin} || $a->{name} cmp $b->{name} } @internal;

print "TOP 25 internal symbols by fan-in:\n";
for my $i (0 .. (scalar(@internal) > 24 ? 24 : scalar(@internal)-1)) {
    my $e = $internal[$i];
    my $rel = $e->{file};
    $rel =~ s/^\Q$REPO\E\/?//;
    print sprintf("%3d  fan-in=%d  %s.%s  (%s)\n", $i+1, $e->{fanin}, $e->{pkg}, $e->{name}, $rel);
}

if (@internal) {
    my $top = $internal[0];
    print "\n=== WINNER ===\n";
    print "symbol: $top->{pkg}.$top->{name}\n";
    print "file: $top->{file}\n";
    print "fan-in: $top->{fanin}\n";
    print "all callers:\n";
    for my $caller (sort keys %{$top->{callers}}) {
        print "  $caller\n";
    }
}

# Also print util.GenUUID for verification
for my $e (@internal) {
    if ($e->{name} eq 'GenUUID' && $e->{pkg} =~ /internal\/util$/) {
        print "\n=== util.GenUUID ===\n";
        print "fan-in: $e->{fanin}\n";
        for my $caller (sort keys %{$e->{callers}}) {
            print "  $caller\n";
        }
        last;
    }
}

