sub parse_imports {
    my ($content) = @_;
    my %imports;
    my @dot;
    while ($content =~ /\bimport\s+(?:\(\s*([\s\S]*?)\)|"([^"]+)"|(\w+)\s+"([^"]+)")/g) {
        if ($1) {
            my $block = $1;
            while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
                my ($alias, $path) = ($1, $2);
                if (!defined $alias) {
                    $alias = $path;
                    $alias =~ s/.*\///;
                }
                if ($alias eq '.') {
                    push @dot, $path;
                } else {
                    $imports{$alias} = $path;
                }
            }
        } elsif ($2) {
            my $path = $2;
            my $alias = $path;
            $alias =~ s/.*\///;
            $imports{$alias} = $path;
        } elsif ($3 && $4) {
            my ($alias, $path) = ($3, $4);
            if ($alias eq '.') {
                push @dot, $path;
            } else {
                $imports{$alias} = $path;
            }
        }
    }
    return (\%imports, \@dot);
}

