#!/usr/bin/perl
use strict;
use warnings;

my $REPO = '/bench/repo';
my $MODULE = 'github.com/usememos/memos';

my %symbols;
my %pkg_funcs;
my %files;

sub sym_key {
    my ($pkg_path, $display) = @_;
    return "${pkg_path}::${display}";
}

sub strip_go_comments {
    my ($s) = @_;
    $s =~ s/\/\*.*?\*\///gs;
    $s =~ s/\/\/.*$//mg;
    return $s;
}

sub pkg_import_path {
    my ($filepath) = @_;
    my $rel = $filepath;
    $rel =~ s/^\Q$REPO\E\/?//;
    $rel =~ s/\/[^\/]+$//;
    return $MODULE . ($rel ? "/$rel" : '');
}

sub parse_imports {
    my ($content) = @_;
    my %imports;
    my @dot;
    while ($content =~ /\bimport\s+(?:\(\s*([\s\S]*?)\)|"([^"]+)"|(\w+)\s+"([^"]+)")/g) {
        if ($1) {
            my $block = $1;
            while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
                my ($alias, $path) = ($1, $2);
                if (!defined $alias) {
                    $alias = $path;
                    $alias =~ s/.*\///;
                }
                if ($alias eq '.') {
                    push @dot, $path;
                } else {
                    $imports{$alias} = $path;
                }
            }
        } elsif ($2) {
            my $path = $2;
            my $alias = $path;
            $alias =~ s/.*\///;
            $imports{$alias} = $path;
        } elsif ($3 && $4) {
            my ($alias, $path) = ($3, $4);
            if ($alias eq '.') {
                push @dot, $path;
            } else {
                $imports{$alias} = $path;
            }
        }
    }
    return (\%imports, \@dot);
}

sub register_symbol {
    my ($sym_id, $file, $pkg_path, $display_name, $recv) = @_;
    if (!exists $symbols{$sym_id}) {
        $symbols{$sym_id} = {
            file => $file,
            pkg => $pkg_path,
            name => $display_name,
            recv => $recv,
            callers => {},
        };
        $pkg_funcs{$pkg_path}{$display_name} = $sym_id;
        if ($recv && $recv =~ /^\*(.+)$/) {
            my $bare_type = $1;
            if ($display_name =~ /^(.+)\.(.+)$/) {
                my ($rtype, $mname) = ($1, $2);
                if ($rtype eq $recv) {
                    $pkg_funcs{$pkg_path}{"${bare_type}.${mname}"} = $sym_id
                        unless exists $pkg_funcs{$pkg_path}{"${bare_type}.${mname}"};
                }
            }
        }
    }
}

sub extract_declarations {
    my ($file, $content, $pkg_path) = @_;
    while ($content =~ /\bfunc\s+(?:\((\w+)\s+(\*?\w+)\)\s+)?(\w+)\s*\(/g) {
        my ($recv_var, $recv_type, $name) = ($1, $2, $3);
        my ($display, $recv);
        if (defined $recv_type) {
            $display = "${recv_type}.${name}";
            $recv = $recv_type;
        } else {
            $display = $name;
            $recv = '';
        }
        register_symbol(sym_key($pkg_path, $display), $file, $pkg_path, $display, $recv);
    }
}

sub resolve_pkg_from_alias {
    my ($alias, $imports) = @_;
    return $imports->{$alias} if exists $imports->{$alias};
    return undef;
}

sub add_call {
    my ($target_sym_id, $caller_id) = @_;
    return unless defined $target_sym_id && defined $caller_id;
    return if $target_sym_id eq $caller_id;
    return unless exists $symbols{$target_sym_id};
    $symbols{$target_sym_id}{callers}{$caller_id} = 1;
}

sub resolve_call_target {
    my ($pkg_alias, $func_name, $imports, $dot_imports, $local_pkg_path) = @_;
    my @targets;
    if (defined $pkg_alias) {
        my $pkg_path = resolve_pkg_from_alias($pkg_alias, $imports);
        if ($pkg_path && exists $pkg_funcs{$pkg_path}{$func_name}) {
            push @targets, $pkg_funcs{$pkg_path}{$func_name};
        }
        for my $dp (@$dot_imports) {
            if (exists $pkg_funcs{$dp}{$func_name}) {
                push @targets, $pkg_funcs{$dp}{$func_name};
            }
        }
    } else {
        if (exists $pkg_funcs{$local_pkg_path}{$func_name}) {
            push @targets, $pkg_funcs{$local_pkg_path}{$func_name};
        }
        for my $dp (@$dot_imports) {
            if (exists $pkg_funcs{$dp}{$func_name}) {
                push @targets, $pkg_funcs{$dp}{$func_name};
            }
        }
    }
    return @targets;
}

sub extract_brace_block {
    my ($text, $start) = @_;
    my $depth = 0;
    my $pos = $start;
    my $len = length($text);
    while ($pos < $len) {
        my $c = substr($text, $pos, 1);
        if ($c eq '{') { $depth++; }
        elsif ($c eq '}') {
            $depth--;
            if ($depth == 0) {
                return substr($text, $start, $pos - $start + 1);
            }
        }
        $pos++;
    }
    return substr($text, $start);
}

sub extract_calls_in_file {
    my ($file, $content, $meta) = @_;
    my $local_pkg_path = $meta->{import_path};
    my $imports = $meta->{imports};
    my $dot_imports = $meta->{dot_imports};

    my @parts = split(/\b(func\s+)/, $content);
