        }
        my $caller_id = sym_key($local_pkg_path, $caller_display);
        process_body($func_body, $caller_id, $local_pkg_path, $imports, $dot_imports);
        }
    }
}

sub process_body {
    my ($body, $default_caller, $local_pkg_path, $imports, $dot_imports) = @_;
    my $work = $body;

