      m=re.match(r'(?:\(\w+\s+\*?\w+\)\s+)?(\w+)\s*\([^)]*\)(?:\s*\([^)]*\)|\s+\*?[\w\.]+)*\s*\{', parts[i], re.S)
      if not m: continue
